115	// scrollPosition is "Lines a-b of N" when the content is taller than the
116	// viewport, "" otherwise.
117	func scrollPosition(offset, visible, total int) string {
118		if visible <= 0 || total <= visible {
119			return ""
120		}
121		offset = max(offset, 0)
122		return fmt.Sprintf("Lines %d-%d of %d", offset+1, min(offset+visible, total), total)
123	}
124	
125	// normalizeText makes a scanner's text safe to lay out: a tab or a carriage
126	// return has no width the viewport and the terminal agree on, trailing spaces
127	// are noise, and a run of blank lines is one blank line. dropBlank removes the
128	// blank lines altogether (a stderr, where they separate nothing).
129	func normalizeText(text string, dropBlank bool) string {
130		text = strings.ReplaceAll(strings.ReplaceAll(text, "\r", ""), "\t", "    ")
131		var out []string
132		for _, line := range strings.Split(text, "\n") {
133			line = strings.TrimRight(line, " ")
134			blank := line == ""
135			switch {
136			case blank && (dropBlank || len(out) == 0 || out[len(out)-1] == ""):
137			default:
138				out = append(out, line)
139			}
140		}
141		for len(out) > 0 && out[len(out)-1] == "" {
142			out = out[:len(out)-1]
143		}
144		return strings.Join(out, "\n")
145	}
146	
147	// dropBlankLines is normalizeText without any blank line.
148	func dropBlankLines(text string) string { return normalizeText(text, true) }
149	
150	// detailsText lays text out for the finding detail: every line it returns is
151	// styled on the theme background and spans at most width cells, measured with
152	// x/ansi as the viewport does.
153	type detailsText struct {
154		width int            // cells a line may span
155		text  lipgloss.Style // ordinary text
156		dim   lipgloss.Style // secondary text
157	}
158	
159	func newDetailsText(width int) detailsText {
160		return detailsText{
161			width: width,
162			text:  lipgloss.NewStyle().Background(theme.ColorBackground).Foreground(theme.ColorText),
163			dim:   theme.DimStyle,
164		}
165	}
