167	// block wraps text at the full width, one styled line per entry.
168	func (t detailsText) block(text string, style lipgloss.Style) []string {
169		return t.indented("", text, style)
170	}
171	
172	// indented wraps text under a prefix of spaces.
173	func (t detailsText) indented(prefix, text string, style lipgloss.Style) []string {
174		text = normalizeText(text, false)
175		if text == "" {
176			return nil
177		}
178		room := max(t.width-ansi.StringWidth(prefix), 1)
179		var lines []string
180		for _, line := range strings.Split(ansi.Wrap(text, room, ""), "\n") {
181			line = strings.TrimRight(line, " ")
182			if line == "" {
183				lines = append(lines, "")
184				continue
185			}
186			lines = append(lines, theme.Bg(prefix)+style.Render(line))
187		}
188		return lines
189	}
190	
191	// field is a label and its value, the value wrapped under itself. When the label
192	// leaves too little room for the value, the value goes on the lines below.
193	func (t detailsText) field(label, value string, style lipgloss.Style) []string {
194		value = normalizeText(value, false)
195		if value == "" {
196			return nil
197		}
198		labelWidth := ansi.StringWidth(label)
199		if t.width-labelWidth < minFieldValueWidth {
200			return append([]string{theme.SubTitleStyle.Render(strings.TrimRight(label, " "))}, t.block(value, style)...)
201		}
202		lines := strings.Split(ansi.Wrap(value, t.width-labelWidth, ""), "\n")
203		out := make([]string, 0, len(lines))
204		for i, line := range lines {
205			line = style.Render(strings.TrimRight(line, " "))
206			if i == 0 {
207				out = append(out, theme.SubTitleStyle.Render(label)+line)
208			} else {
209				out = append(out, theme.Bg(strings.Repeat(" ", labelWidth))+line)
210			}
211		}
212		return out
213	}
214	
215	// minFieldValueWidth is the least room a value needs beside its label.
216	const minFieldValueWidth = 12
