19	func fixStatusOf(f scan.Finding, onDisk bool) fixStatus {
20		switch scan.Categorize(f) {
21		case scan.CategoryVulnerability:
22			if f.FixedIn != "" {
23				return fixStatus{Label: "Fix available", Detail: "Fixed in " + f.FixedIn}
24			}
25			return fixStatus{Label: "No fix available", Detail: "No fixed version is published"}
26		case scan.CategoryMisconfiguration:
27			return misconfigFixStatus(f, onDisk)
28		}
29		return fixStatus{}
30	}
31	
32	func misconfigFixStatus(f scan.Finding, onDisk bool) fixStatus {
33		rule, a := misconfigFixAvailability(f, onDisk)
34		inCatalog := rule.AVDID != ""
35		switch {
36		case a.Enabled():
37			return fixStatus{Label: "Built-in fix available", Detail: rule.Title, Warning: rule.Warning}
38		case !onDisk && inCatalog:
39			return fixStatus{Label: "No built-in fix here", Detail: a.Reason}
40		case !inCatalog:
41			// On an image the availability reason is the image one; the finding's own
42			// reason is what explains the missing fix.
43			return fixStatus{Label: "No built-in fix", Detail: noFixReason(f)}
44		}
45		return fixStatus{Label: "No built-in fix for this instance", Detail: a.Reason}
46	}
47	
48	// fixAction says how to show f.FixCommand: ("Run", cmd) for a real command,
49	// ("", instruction) for a sentence such as "Update pkg to 1.2", ("", "") when
50	// there is none.
51	func fixAction(f scan.Finding) (label, text string) {
52		switch {
53		case f.FixCommand == "":
54			return "", ""
55		case scan.IsFixInstruction(f):
56			return "", f.FixCommand
57		}
58		return "Run", f.FixCommand
59	}
